mapper.sql:
FROM lectures JOIN courses ON lectures.course_id = courses.id JOIN departments ON courses.department_id = departments.id LEFT JOIN colleges ON departments.college_id = colleges.id JOIN professors ON lectures.professor_id = professors.id JOIN users ON professors.user_id = users.id JOIN semesters ON lectures.semester_id = semesters.id
AND courses.name LIKE CONCAT('%', #{searchReq.courseName}, '%')
AND users.name LIKE CONCAT('%', #{searchReq.professorName}, '%')
AND departments.name LIKE CONCAT('%', #{searchReq.departmentName}, '%')
AND colleges.name LIKE CONCAT('%', #{searchReq.collegeName}, '%')
AND courses.target_grade = #{searchReq.targetGrade}
AND semesters.academic_year = #{searchReq.year}
AND semesters.term = IF(#{searchReq.semester} = 1, 'FIRST', 'SECOND')
AND courses.code = #{searchReq.courseCode}
